import { Controller } from "@hotwired/stimulus"
import { Turbo } from "@hotwired/turbo-rails"
import { post, destroy } from "@rails/request.js"

export default class extends Controller {
  static targets = [ "card" ]

  #card
  #hoveredColumn
  #saves = Promise.resolve()

  cardTargetConnected(card) {
    card.draggable = true
  }

  cardTargetDisconnected(card) {
    card.removeAttribute("draggable")
  }

  preserveDraggable(event) {
    if (event.detail.attributeName === "draggable" && event.target.draggable) event.preventDefault()
  }

  start(event) {
    if (!this.cardTargets.includes(event.target)) return

    this.#card = event.target
    event.dataTransfer.effectAllowed = "move"
    event.dataTransfer.setData("text/plain", this.#card.id)
    this.#card.classList.add("drag-and-drop__dragged-item")
  }

  over(event) {
    if (this.#canDrop(event.currentTarget)) {
      event.preventDefault()
      event.dataTransfer.dropEffect = "move"
      this.#highlight(event.currentTarget)
    }
  }

  leave({ currentTarget, relatedTarget }) {
    if (currentTarget === this.#hoveredColumn && !currentTarget.contains(relatedTarget)) this.#highlight(null)
  }

  drop(event) {
    const column = event.currentTarget
    if (!this.#canDrop(column)) return

    event.preventDefault()
    const card = this.#card
    this.end()
    this.#move(card, column)
  }

  end() {
    this.#card?.classList.remove("drag-and-drop__dragged-item")
    this.#card = null
    this.#highlight(null)
  }

  disconnect() {
    this.end()
  }

  #canDrop(column) {
    return this.#card && !column.contains(this.#card) && column.querySelector(".cards__list turbo-frame")
  }

  #highlight(column) {
    if (this.#hoveredColumn !== column) {
      this.#hoveredColumn?.classList.remove("drag-and-drop__hover-container")
      column?.classList.add("drag-and-drop__hover-container")
      this.#hoveredColumn = column
    }
  }

  #move(original, column) {
    const source = original.closest(".cards")
    const card = original.cloneNode(true)
    const position = document.createComment("card position")
    original.replaceWith(position)
    this.#insert(card, column)
    this.#updateCount(source, -1)
    this.#updateCount(column, 1)

    // Commit in drop order, even when several moves are made on a slow connection.
    this.#saves = this.#saves.then(async () => {
      try {
        const response = await this.#save(card, column)
        if (!response.ok) throw new Error(`Card move failed: ${response.statusCode}`)
        const preview = new DOMParser().parseFromString(await response.html, "text/html").querySelector("article.card")
        if (!preview || preview.id !== card.id) throw new Error("Missing card preview")
        if (card.isConnected) Turbo.morphElements(card, preview)
      } catch (error) {
        if (card.isConnected) {
          card.remove()
          position.replaceWith(original)
          this.#updateCount(column, -1)
          this.#updateCount(source, 1)
        }
        console.error(error)
      } finally {
        position.remove()
      }
    })
  }

  #insert(card, column) {
    const active = column.id === "maybe" || !!column.dataset.columnId
    card.classList.toggle("card--active", active)
    card.classList.toggle("card--postponed", column.id === "not-now")
    card.style.setProperty("--card-color", column.style.getPropertyValue("--card-color") || "var(--color-card-default)")
    card.querySelector(".card__closed")?.remove()
    card.querySelector(".bubble")?.remove()
    card.removeAttribute("aria-selected")

